class _Ctx:
    """v1.12 묶음 하나의 요청 상태 — 마지막 요청 시각(묶음 안 GAP) · 세션(넘겨짐 사이 쿠키) · 값 하나의 로그 줄"""
    def __init__(self):
        self.last, self.sess, self.buf = 0.0, requests.Session(), None


_MAIN = _Ctx()   # 차례대로 받을 때(PRICE_LANES=1 — 예전처럼 모든 요청이 한 줄로 GAP)·스레드 밖


def _ctx():
    return getattr(_TL, "c", None) or _MAIN


def _lock(d, k):
    with _GUARD:
        return d.setdefault(k, threading.Lock())
# robots.txt를 두지 않는 API 주소 → 같은 회사 대표 사이트 robots.txt를 따름(그 사이트 robots.txt도 못 받으면 건너뜀)
# api.nike.com: 상품 정보 경로 밖 모든 주소(/, robots.txt, 없는 주소)에 Akamai가 '503 DNS failure' — 2026-10-21 브랜치 시험에서 확인
ROBOTS_ALT = {"api.nike.com": "https://www.nike.com"}


def _robots_rules(txt):
    """robots.txt → 지킬 규칙 묶음 [[(허용?, 정규식, 길이)], …] — v1.31: * 그룹 + (있으면) 옛 이름 그룹 + (있으면) 새 이름 그룹을 모두 지킴
    (어느 묶음 하나라도 막으면 막음 — 옛 이름 그룹은 이름을 바꿔 피하지 않게, 새 이름 그룹은 아직 아무 사이트도 우리 새 이름을 몰라 다른 봇 것일 수
    있어 *보다 넓게 허용하지 않게 · 전에는 RFC 9309대로 우리 이름 그룹이 있으면 그것만, 없으면 *)"""
    groups, g, rule_seen = [], None, True
    for line in txt.splitlines():
        line = line.split("#", 1)[0].strip()
        if ":" not in line: continue
        k, v = (x.strip() for x in line.split(":", 1)); k = k.lower()
        if k == "user-agent":
            if rule_seen: g = {"ua": set(), "rules": []}; groups.append(g); rule_seen = False
            g["ua"].add(v.lower())
        elif k in ("allow", "disallow") and g is not None:
            rule_seen = True
            if v:   # %2A·%24는 글자 그대로(와일드카드·끝 표시가 아님)
                lit = re.sub(r"%2[aA]", "\x00", re.sub(r"%24", "\x01", v))
                rx = re.escape(urllib.parse.unquote(lit)).replace(r"\*", ".*")
                if rx.endswith(r"\$"): rx = rx[:-2] + "$"
                rx = rx.replace("\x00", r"\*").replace("\x01", r"\$")
                g["rules"].append((k == "allow", re.compile(rx), len(v)))
    sets = [[r for gg in groups if "*" in gg["ua"] for r in gg["rules"]]]
    for name in (OLD_BOT, BOT):
        if any(name in gg["ua"] for gg in groups):
            sets.append([r for gg in groups if name in gg["ua"] for r in gg["rules"]])
    return sets


def _robots_get(base):
    """규칙 목록, 또는 못 받은 이유(글) — 4xx면 규칙 없음, 429·5xx·연결 안 됨이면 이유(RFC 9309: 그 사이트 전체를 막힌 것으로)"""
    try:
        r = requests.get(base + "/robots.txt", headers=HDR, timeout=20)
        if r.status_code == 429 or r.status_code >= 500:
            return f"robots.txt HTTP {r.status_code}"
        if r.status_code != 200:
            return []
        raw = getattr(r, "content", None)
        return _robots_rules(raw.decode("utf-8", "replace") if isinstance(raw, bytes) else r.text)   # 글자 집합 표시가 없어도 UTF-8
    except requests.RequestException as e:
        return f"robots.txt 못 받음({type(e).__name__})"


def robots_ok(url):
    """(허용?, 이유) — 사이트별 robots.txt는 실행마다 1번만 받음"""
    p = urllib.parse.urlsplit(url); base = f"{p.scheme}://{p.netloc}"
    if base not in _ROB:
        _ROB[base] = _robots_get(base)
        alt = ROBOTS_ALT.get(p.netloc)
        if isinstance(_ROB[base], str) and alt:
            got = _robots_get(alt)
            if not isinstance(got, str):
                if not _QUIET[0]:   # v1.29 SKU 단계에서는 찍지 않음(어느 브랜드를 묻는지가 드러나지 않게)
                    log(f"  {p.netloc}: {_ROB[base]} — robots.txt를 두지 않는 API 주소라 {urllib.parse.urlsplit(alt).netloc} robots.txt를 따름")
                _ROB[base] = got
        if not isinstance(_ROB[base], str) and len(_ROB[base]) > 1 and not _QUIET[0]:
            log(f"  {p.netloc}: robots.txt에 우리 이름(옛 이름·새 이름) 그룹이 있음 — * 규칙과 함께 모두 지킴(더 엄격한 쪽)")
    rules = _ROB[base]
    if isinstance(rules, str):
        return False, f"{rules} — 이 사이트 건너뜀"
    path = urllib.parse.unquote(p.path or "/") + ("?" + urllib.parse.unquote(p.query) if p.query else "")
    for rs in rules:   # v1.31 묶음마다 가장 긴 규칙 — 하나라도 막으면 막음
        hit = [(n, a) for a, rx, n in rs if rx.match(path)]
        if hit and not max(hit)[1]:
            return False, "robots.txt가 막음"
    return True, ""


_S = _MAIN.sess   # 넘겨짐 사이 쿠키를 이어 주려고(예전 allow_redirects=True와 같게) · v1.12 묶음마다 세션(_Ctx.sess)


CHALLENGE = re.compile(r"(?is)<title[^>]*>\s*(?:Client Challenge|Just a moment\.\.\.|Attention Required|Access Denied|Pardon Our Interruption)\s*</title>"
                       r"|/_fs-ch-|challenges\.cloudflare\.com|captcha-delivery\.com|px-captcha")


def _challenge(r):
    """v1.22 응답이 봇 확인 화면인지 — HTML이고 작으며(30KB 밑) 확인 화면 제목·표식이 있을 때만(큰 상품 페이지 본문의 낱말에 걸리지 않게)"""
    h = getattr(r, "headers", None) or {}
    body = getattr(r, "content", None)
    ct = (h.get("Content-Type") or "").lower()
    if (ct and "html" not in ct) or body is None or len(body) > 30000:
        return False
    return bool(CHALLENGE.search(getattr(r, "text", "") or ""))


def get(url, hops=5):
    """주소 → 응답. 넘겨짐(3xx)은 직접 따라가며 매번 막힘·robots.txt를 먼저 확인(막힌 주소는 요청하지 않음).
    v1.12 그 사이트 자물쇠 안에서 확인·기다림·요청(같은 사이트는 묶음과 상관없이 한 번에 한 요청) — 기다림 = 묶음 안 GAP과
    같은 사이트 GAP(살로몬 해외 HOST_GAP) 중 긴 것, 플랫폼(PACE)이면 플랫폼 자물쇠 안에서 플랫폼 GAP도(그 몰의 robots.txt도 ·
    플랫폼 몰이 다른 이름 사이트로 넘기면 그 사이트도 같은 플랫폼으로). 넘겨짐은 자물쇠를 풀고 따라감 · 멈춤(_STOP)은 요청 바로 전에도 확인"""
    c, moved, g0 = _ctx(), False, None
    for _ in range(hops + 1):
        p = urllib.parse.urlsplit(url); host = p.netloc
        pre = "넘겨진 주소: " if moved else ""
        g = _PACE.get(host) or g0
        with _lock(_HLOCK, host):
            if _STOP.is_set():
                raise RuntimeError(pre + "묶음을 멈춤(시간 초과·다른 묶음 오류) — 더 요청 안 함")
            if host in _BLOCKED:
                raise RuntimeError(pre + "이번 실행에서 이 사이트가 막음 — 더 요청 안 함")
            if g in _GBLOCKED:
                raise RuntimeError(pre + f"이번 실행에서 이 플랫폼({g})이 막음(430) — 더 요청 안 함")
            if _DOWN.get(host, 0) >= 2:
                raise RuntimeError(pre + "이번 실행에서 이 사이트가 연달아 응답 없음 — 더 요청 안 함")
            if g and f"{p.scheme}://{host}" not in _ROB:   # 플랫폼 몰의 robots.txt도 플랫폼 줄에 맞춰(앞 요청이 끝나고 GAP 뒤)
                with _lock(_GLOCK, g):
                    w = GAP - (time.time() - _GLAST.get(g, 0.0))
                    if w > 0: time.sleep(w)
                    _GLAST[g] = time.time()
                    robots_ok(url)
            ok, why = robots_ok(url)
            if not ok:
                raise RuntimeError(pre + why)
            if host in HOST_CAP and _HCOUNT.get(host, 0) >= HOST_CAP[host]:
                raise Defer(f"{host} 한 실행 요청 한도 {HOST_CAP[host]}건")
            w = max(GAP - (time.time() - c.last), max(GAP, HOST_GAP.get(host, 0)) - (time.time() - _HLAST.get(host, 0.0)))
            if w > 0: time.sleep(w)
            with (_lock(_GLOCK, g) if g else contextlib.nullcontext()):   # 플랫폼은 묶음을 넘어 한 줄로(앞 요청이 끝나고 GAP 뒤)
                if g:
                    w = GAP - (time.time() - _GLAST.get(g, 0.0))
                    if w > 0: time.sleep(w)
                if _STOP.is_set():   # 기다리는 사이 멈춤 — 요청하지 않음(한도 셈도 안 씀)
                    raise RuntimeError(pre + "묶음을 멈춤(시간 초과·다른 묶음 오류) — 더 요청 안 함")
                _HCOUNT[host] = _HCOUNT.get(host, 0) + 1
                c.last = _HLAST[host] = time.time()
                if g:
                    _GLAST[g] = c.last
                try:
                    r = c.sess.get(url, headers=HDR, timeout=25, allow_redirects=False)
                except (requests.exceptions.ConnectionError, requests.exceptions.Timeout):
                    _DOWN[host] = _DOWN.get(host, 0) + 1   # v1.3 같은 사이트가 연달아 2번 응답 없으면 이번 실행에서 건너뜀(한 사이트가 시간 제한을 다 쓰지 않게)
                    raise
            _DOWN.pop(host, None)
            loc = (getattr(r, "headers", None) or {}).get("Location") if 300 <= r.status_code < 400 else None
            if not loc:
                if r.status_code in (403, 429, 430):   # v1.12 430 = 쇼피파이가 우리 서버(IP)를 거절
                    _BLOCKED.add(host)   # 실제로 막은 사이트
                    if r.status_code == 430 and g:
                        _GBLOCKED.add(g)   # 플랫폼이 거절 — 그 실행에서 같은 플랫폼 몰 모두 더 요청 안 함
                    raise RuntimeError(pre + f"HTTP {r.status_code}(접속 차단 — 우회하지 않음)")
                if r.status_code >= 400:
                    raise RuntimeError(pre + f"HTTP {r.status_code}")
                if _challenge(r):   # v1.22 HTTP 200인데 봇 확인 화면(언더아머 한국·영국·독일 11/17 'Client Challenge') — 403처럼 그 실행에서 더 요청 안 함
                    _BLOCKED.add(host)
                    raise RuntimeError(pre + "봇 확인 화면(접속 차단 — 우회하지 않음)")
                return r
        try:
            loc = loc.encode("latin1").decode("utf-8")   # requests와 같게 UTF-8 주소 되살림
        except (UnicodeEncodeError, UnicodeDecodeError):
            pass
        url, moved, g0 = urllib.parse.urljoin(url, loc), True, g
    raise RuntimeError(f"넘겨짐이 {hops}번 넘음")


def _json(r):
    d = r.json()
    if not isinstance(d, dict):
        raise RuntimeError("응답 형식이 다름")
    return d


def num(v):
    try:
        x = float(str(v).replace(",", ""))
        return x if x > 0 else None
    except (TypeError, ValueError):
        return None


def _money(s):
    """화면 글자 가격 → 숫자: '$1,234.56' · '1.234,56 €' · '190,00' · '1.234 €'(독일식 천 단위) — '&#8364;'(€) 같은 HTML 기호는 먼저 풂(숫자가 섞이지 않게)"""
    t = re.sub(r"[^0-9.,]", "", unescape(str(s)))
    if re.fullmatch(r"\d{1,3}(\.\d{3})*,\d{1,2}", t):
        t = t.replace(".", "").replace(",", ".")
    elif re.fullmatch(r"\d{1,3}(\.\d{3})+", t):
        t = t.replace(".", "")
    return num(t)


def _micro(html, cur, codes):
    """schema.org 마이크로데이터(itemprop) 가격 — JSON-LD가 없는 SFCC형 몰(써코니 해외). 이 상품 품번(data-stock-number)이 있을 때만.
    판매가 = itemprop price(같이 있는 priceincents ÷ 100 우선 — 190,00 같은 독일식 표기 오해 방지), 정가 = 판매가 바로 뒤 '원래 가격'(price-standard)"""
    stock = " ".join(re.findall(r'data-stock-number="([^"]+)"', html)).lower()
    if not codes or not any(c in stock for c in codes):
        return [], [], False
    offers, end = [], 0
    for m in re.finditer(r'itemprop="priceCurrency"[^>]*>\s*([A-Z]{3})\s*<.{0,300}?itemprop="price"[^>]*>\s*([0-9][0-9.,]*)\s*<'
                         r'(?:(?:(?!itemprop="priceCurrency").){0,200}?itemprop="priceincents"[^>]*>\s*([0-9]+)\s*<)?', html, re.S):   # 다음 가격 칸의 priceincents를 가져오지 않게
        c, p, cents = m.groups()
        v = (int(cents) / 100 if cents else None) or _money(p)
        if c == cur and v:
            offers.append(v); end = m.end()
    lists = []
    for m in re.finditer(r'class="price-sales[^"]*"[^>]*>\s*([^<]*?)\s*<(?:(?!class="price-sales).){0,300}?class="price-standard[^"]*"[^>]*>\s*([^<]*?)\s*<',
                         html[:end], re.S):   # 이 상품 가격 칸(마이크로데이터) 앞만 · 바로 다음 판매가 칸 전까지 — 추천 상품 칸의 원래 가격과 짝짓지 않게
        sv, lv = _money(m.group(1)), _money(m.group(2))
        if sv and lv and sv <= lv <= sv * 3 and any(abs(sv - o) < 0.01 for o in offers):
            lists.append(lv)
    return offers, lists, True


def nike_price(code, cc):
    m, l, cur = MK[cc]
    if not m:   # v1.17 나이키 상품 정보에 없는 나라(두바이 — AE는 정가 100000 자리표시) — 나이키 상품 urls의 페이지로
        raise RuntimeError("나이키 상품 정보에 이 나라 없음 — 상품 urls에 페이지 주소 필요")
    d = _json(get(NIKE_FEED.format(m=m, l=l, s=code)))
    objs = [o for o in d.get("objects") or [] if isinstance(o, dict)]
    if not objs:
        raise Skip("이 나라 나이키에서 팔지 않음")
    for o in objs:
        for pi in o.get("productInfo") or []:
            mp, mer = pi.get("merchPrice") or {}, pi.get("merchProduct") or {}
            if mer.get("styleColor") != code:
                continue
            fp = num(mp.get("fullPrice"))
            if fp and mp.get("currency") == cur:
                return fp, {"cur_price": num(mp.get("currentPrice"))}
    raise RuntimeError("정가(fullPrice) 없음")


REL = {"isSimilarTo", "isRelatedTo", "isAccessoryOrSparePartFor", "isConsumableFor", "itemListElement"}   # 관련·추천 상품 칸


def _ld_nodes(html, skip=()):
    out = []
    for m in re.finditer(r'<script[^>]+application/ld\+json[^>]*>(.*?)</script>', html, re.S | re.I):
        try:
            d = json.loads(m.group(1).strip())
        except ValueError:
            continue
        st = [d]
        while st:
            x = st.pop()
            if isinstance(x, list):
                st.extend(x)
            elif isinstance(x, dict):
                out.append(x)
                st.extend(v for k, v in x.items() if isinstance(v, (dict, list)) and k not in skip)
    return out


def _types(n):
    t = n.get("@type")
    return {str(x).lower() for x in (t if isinstance(t, list) else [t])}


def page_price(html, hint, cur, codes=()):
    """상품 페이지 → 정가. 글로벌 품번(codes)이 품번·주소에 있는 JSON-LD 상품만 보고, 그런 상품이 없을 때만 이름에 모델명(hint)이
    낱말로 있는 상품을 봄(추천·관련 상품 섞임 방지)"""
    offers, lists = [], []
    codes = [c.lower() for c in codes if c]
    nodes = [n for n in _ld_nodes(html) if _types(n) & {"product", "productgroup"}]
    word = re.compile(rf"(?<![\w-]){re.escape(hint)}(?![\w-])")
    by_code = [n for n in nodes if any(c in " ".join(str(n.get(k, "")) for k in ("sku", "productID", "productGroupID", "mpn", "url", "@id")).lower() for c in codes)]
    prods = by_code
    if not by_code:   # 품번이 없으면 이름으로 — 관련·추천 상품 칸은 빼고, 이름이 다른 상품이 여럿이면 실패(틀린 값을 저장하지 않게)
        prods = [n for n in _ld_nodes(html, REL) if _types(n) & {"product", "productgroup"} and word.search(str(n.get("name", "")).lower())]
        names = {str(n.get("name", "")).strip().lower() for n in _ld_nodes(html, REL | {"hasVariant"})
                 if _types(n) & {"product", "productgroup"} and word.search(str(n.get("name", "")).lower())}
        if len(names) > 1:
            raise RuntimeError(f"품번이 없고 이름이 비슷한 상품이 여럿({' / '.join(sorted(names))[:60]})")
    for p in prods:
        st = [p.get("offers"), p.get("hasVariant")]
        while st:
            x = st.pop()
            if isinstance(x, list): st.extend(x); continue
            if not isinstance(x, dict): continue
            if _types(x) & {"product"}: st.append(x.get("offers")); continue
            if str(x.get("priceCurrency", cur)) == cur:
                v = num(x.get("price") or x.get("highPrice") or x.get("lowPrice"))
                if v: offers.append(v)
            for ps in (x.get("priceSpecification") if isinstance(x.get("priceSpecification"), list) else [x.get("priceSpecification")]):
                if isinstance(ps, dict) and re.search(r"ListPrice|StrikethroughPrice", str(ps.get("priceType", ""))) and str(ps.get("priceCurrency", cur)) == cur:
                    v = num(ps.get("price"))
                    if v: lists.append(v)
            if x.get("offers"): st.append(x.get("offers"))
    flat = html.replace('\\"', '"')
    # SFCC형 몰(푸마 멕시코): 화면 데이터의 c_listPrice(정가)·c_salePrice(판매가) — 판매가가 이 상품 가격과 같을 때만(추천 상품 섞임 방지)
    for m in re.finditer(r'"c_listPrice":([0-9.]+),"c_salePrice":([0-9.]+)', flat):
        lp, sp = num(m.group(1)), num(m.group(2))
        if lp and sp and sp <= lp <= sp * 3 and any(abs(sp - o) < 0.01 for o in offers):
            lists.append(lp)
    # SFCC형 몰(푸마 한국 등): 가격인하 중이면 JSON-LD에는 판매가만 — 이 상품 가격 칸의 취소선 정가(strike-through list)를 정가로.
    # 이 상품 것만: 취소선 바로 곁 판매가 칸(sales — 푸마 한국은 취소선 바로 앞, SFCC 기본은 바로 뒤)의 값이 이 상품 판매가(JSON-LD)와 같을 때만
    # (추천 상품 칸의 할인 가격을 가져오지 않게) · 그런 정가가 한 가지일 때만 · 판매가보다 높고 5배 안(70% 할인까지 — 푸마 한국 팔레르모 10/22 119,000 → 35,700원)
    lps = set()
    for m in re.finditer(r'class="strike-through list"[^>]*>\s*(?:<(?!span class="value")[^>]+>\s*)*<span class="value"[^>]*>\s*([^<]+?)\s*</span>', html):
        back = html[max(0, m.start() - 600):m.start()]; k = back.rfind('class="sales')
        seg = back[k:] if k >= 0 else html[m.end():m.end() + 600]
        sm = re.search(r'class="sales[^"]*"(?:(?!strike-through).)*?<span class="value"[^>]*>\s*([^<]+?)\s*</span>', seg, re.S)
        lp, sv = _money(m.group(1)), _money(sm.group(1)) if sm else None
        if lp and sv and any(abs(sv - o) < 0.01 for o in offers) and sv <= lp <= sv * 5:
            lps.add(lp)
    if len(lps) == 1:
        lists.append(lps.pop())
    # 아크테릭스 한국: JSON-LD에는 판매가만 — 화면 데이터의 정가(retail_price). 이 상품 것만(같은 { } 묶음 안에 이 상품 품번) · 판매가(sell·last)가
    # 이 상품 JSON-LD 가격과 같을 때만 · 판매가보다 높고 5배 안
    for m in re.finditer(r'"retail_price":([0-9.]+),"sell_price":([0-9.]+),"last_price":([0-9.]+)', flat):
        back = flat[max(0, m.start() - 400):m.start()]
        if not any(c in back[back.rfind("{") + 1:].lower() for c in codes): continue
        lp, sps = num(m.group(1)), [num(m.group(2)), num(m.group(3))]
        if lp and any(sp and sp <= lp <= sp * 5 and any(abs(sp - o) < 0.01 for o in offers) for sp in sps):
            lists.append(lp)
    # 살로몬 해외: 상품 이름 바로 뒤 기본가(basePrice) — 화면 데이터가 따옴표를 \"로 감싸 둠. 품번이 맞는 것 우선, 없으면 이름(모델명)
    base_code, base_name = set(), set()
    for m in re.finditer(r'"name":"([^"]{0,80})","newModelCodes":\[([^\]]*)\],"price":\{"basePrice":([0-9.]+),"currency":"([A-Z]{3})"', flat):
        v = num(m.group(3))
        if not v or m.group(4) != cur: continue
        if any(c in m.group(2).lower() for c in codes): base_code.add(v)
        elif word.search(m.group(1).lower()): base_name.add(v)
    base = base_code or base_name
    if len(base) > 1:
        raise RuntimeError(f"여러 상품 기본가가 섞임({', '.join(f'{x:g}' for x in sorted(base))})")
    lists.extend(base)
    micro = False
    if not prods and not lists:   # JSON-LD가 없으면 마이크로데이터(써코니 해외 — 품번이 페이지 상품 칸에 있을 때만)
        mo, ml, micro = _micro(html, cur, codes)
        offers += mo; lists += ml
    if not prods and not lists and not micro:
        raise RuntimeError("상품 가격 데이터(JSON-LD) 없음")
    if not offers and not lists:
        raise RuntimeError(f"{cur} 가격 없음")
    full = max(lists) if lists else max(offers)
    if offers and max(offers) > full: full = max(offers)   # 정가 명세보다 높은 판매가는 없으므로 높은 쪽
    return full, {"cur_price": min(offers) if offers else None, "by": "품번" if by_code or base_code or micro else "이름" if prods or base_name else "",
                  "lst": bool(lists)}   # v1.29 정가 표시(정가 명세·취소선 등)로 읽었는지 — SKU 단계 새 값 정가 확인


def cafe24_list(html, sale):
    """v1.13 카페24 몰(브룩스 한국): 할인 중이면 JSON-LD에는 판매가만 — 이 상품 판매가 칸(product_price) 바로 뒤 소비자가 칸(price_custom)을 정가로.
    판매가 칸 값이 이 상품 JSON-LD 판매가와 같을 때만(추천 상품 칸 섞임 방지) · 그런 소비자가가 한 가지일 때만 · 판매가보다 높고 5배 안"""
    lps = set()
    for m in re.finditer(r'class="product_price">\s*([\d,]+)\s*<span>원</span>\s*</p>\s*<p class="price_custom[^"]*">\s*([\d,]+)\s*원', html):
        sv, lp = num(m.group(1)), num(m.group(2))
        if sv and lp and abs(sv - sale) < 0.01 and sv < lp <= sv * 5:
            lps.add(lp)
    return lps.pop() if len(lps) == 1 else None


C24_TAGS = r'(?:<(?:strike|del|s|span|strong|em|b|font)\b[^>]*>\s*){0,3}'   # v1.27 값 앞 꾸밈 태그(여는 태그만 — 빈 칸에서 다음 칸 값으로 넘어가지 않게)
C24_CUSTOM = re.compile(r'id="span_product_price_custom"[^>]*>\s*' + C24_TAGS + r'([\d,]+)\s*원')
C24_TEXT = re.compile(r'id="span_product_price_text"[^>]*>\s*' + C24_TAGS + r'([\d,]+)\s*원')
C24_WIN = 8000   # 글자 — 소비자가 칸 뒤 이만큼 안(다음 소비자가 칸 전)의 판매가 칸만 같은 상품 정보 칸으로 봄
C24_CUSTOM_RAW = re.compile(r'id="span_product_price_custom"[^>]*>((?:(?!</span>).){0,300})', re.S)   # v1.27 소비자가 칸 안 글(꼴 확인용 — '…원' 꼴이 아니어도)


def cafe24_id_list(html, sale):
    """v1.27 카페24 기본 상품 정보 칸(미즈노 한국): 할인 중이면 JSON-LD·meta에는 판매가만 — 이 상품 정보 칸의 소비자가(id="span_product_price_custom",
    <strike>)를 정가로. 이 상품 것만: 소비자가 칸 바로 뒤(C24_WIN 안 · 다음 소비자가 칸 전) 판매가 칸(id="span_product_price_text")과 짝 · 소비자가·판매가가 각각 한 가지 ·
    판매가 칸 = 이 상품 JSON-LD 판매가(sale) · 판매가보다 높고 5배 안 → (정가, 판매가) · 할인 아님(소비자가 = 판매가)이면 (None, 판매가) ·
    소비자가 칸이 없으면 (None, None) · 소비자가가 판매가보다 높은데(할인 표시) 위 조건을 못 맞추거나 소비자가 칸 숫자를 '…원' 꼴로 못 읽으면
    RuntimeError(할인가를 정가로 저장하지 않게)"""
    cus = [(m.start(), num(m.group(1))) for m in C24_CUSTOM.finditer(html)]
    raw = [_money(re.sub(r"<[^>]*>", "", m.group(1))) for m in C24_CUSTOM_RAW.finditer(html)]
    if sum(1 for x in raw if x) > sum(1 for _, lp in cus if lp) and any(x and x > sale * 1.005 for x in raw):   # v1.27 소비자가 칸에 판매가보다 큰 숫자가 있는데 '…원' 꼴로 못 읽음
        raise RuntimeError(f"소비자가 칸 꼴을 못 읽음(칸 안 값 {sorted({x for x in raw if x})} · JSON-LD {sale:g}) — 할인가를 정가로 저장하지 않음")
    if not cus:
        return None, None
    pairs = []
    for i, (at, lp) in enumerate(cus):
        end = min(at + C24_WIN, cus[i + 1][0] if i + 1 < len(cus) else len(html))
        t = C24_TEXT.search(html, at, end)
        if t:
            pairs.append((lp, num(t.group(1))))
    lps, svs = {lp for _, lp in cus}, {sv for _, sv in pairs}
    if pairs and len(lps) == 1 and len(svs) == 1:
        lp, sv = next(iter(lps)), next(iter(svs))
        if lp and sv and abs(sv - sale) < 0.01:
            if abs(lp - sv) < 0.01:
                return None, sv
            if sv < lp <= sv * 5:
                return lp, sv
    if any(lp and lp > sale * 1.005 for _, lp in cus):
        raise RuntimeError(f"소비자가 칸을 이 상품 칸으로 확인 못 함(소비자가 {sorted(x for x in lps if x)} · 판매가 칸 {sorted(x for x in svs if x)} · "
                           f"JSON-LD {sale:g}) — 할인가를 정가로 저장하지 않음")
    return None, (next(iter(svs)) if len(svs) == 1 else None)


BIGC_PAIR = re.compile(r'data-product-non-sale-price-without-tax[^>]*>\s*([^<]*?)\s*</span>'
                       r'(?:(?!data-product-non-sale-price-without-tax).){0,1500}?data-product-price-without-tax[^>]*>\s*([^<]*?)\s*</span>', re.S)   # v1.27


def bigc_list(html, sale):
    """v1.27 빅커머스 몰(미즈노 미국): 할인 중이면 JSON-LD에 판매가만 — 이 상품 가격 칸(price-section)의 할인 전 가격
    (data-product-non-sale-price-without-tax · 할인 없으면 빈 칸)을 정가로. 이 상품 것만: 할인 전 칸 바로 뒤(다음 할인 전 칸 전) 판매가 칸
    (data-product-price-without-tax) 값이 이 상품 JSON-LD 판매가(sale)와 같은 칸끼리 · 정가가 한 가지 · 판매가보다 높고 5배 안 → (정가, 판매가) ·
    할인 전 칸이 모두 비었으면 (None, 판매가) · 빈 칸과 값 칸이 섞이거나(판매가가 같은 다른 상품 카드) 이 상품 가격 칸을 못 찾거나 할인 전 가격을 확인 못 하면
    RuntimeError(할인가·다른 상품 정가를 정가로 저장하지 않게)"""
    mine = [(lv, _money(sv)) for lv, sv in BIGC_PAIR.findall(html)]
    mine = [(lv, sv) for lv, sv in mine if sv and abs(sv - sale) < 0.01]
    if not mine:
        raise RuntimeError(f"빅커머스 가격 칸에서 이 상품 판매가({sale:g})를 못 찾음 — 할인 여부를 몰라 저장하지 않음")
    lps = {_money(lv) if lv.strip() else 0 for lv, _ in mine}   # v1.27 빈 칸(할인 없음)도 한 값(0)으로 셈
    if lps == {0}:
        return None, sale
    if 0 in lps:   # v1.27 빈 할인 전 칸(할인 없음)과 할인 전 값이 섞임 — 판매가가 같은 추천 상품 카드일 수 있어 이 상품 칸을 못 가림
        raise RuntimeError(f"할인 전 칸이 빈 칸과 값({' · '.join(sorted({lv.strip() for lv, _ in mine if lv.strip()}))[:40]})으로 섞임 · 판매가 {sale:g} — 정가 확인 안 됨")
    if len(lps) == 1:
        lp = next(iter(lps))
        if lp and abs(lp - sale) < 0.01:
            return None, sale
        if lp and sale < lp <= sale * 5:
            return lp, sale
    raise RuntimeError(f"할인 전 가격 칸을 확인 못 함({' · '.join(lv for lv, _ in mine if lv.strip())[:60]} · 판매가 {sale:g}) — 할인가를 정가로 저장하지 않음")


SFRA_BOX = re.compile(r'b-pdp__priceline|product-detail__priceline|b-microproduct__price|product-tile')   # v1.17 가격 칸 표시 — 뒤 것(추천 상품 칸)은 이 상품 아님
SFRA_STRIKE = re.compile(r'class="strike-through list"[^>]*>\s*(?:<(?!span class="value")[^>]+>\s*)*<span class="value"[^>]*?content="([0-9][0-9.,]*)"')
SFRA_SALES = re.compile(r'class="sales[^"]*"(?:(?!strike-through).)*?<span class="value"[^>]*?content="([0-9][0-9.,]*)"', re.S)


def sfra_list(html, code, pre, sale):
    """v1.17 두바이 SFCC(SFRA) 몰(nike.ae·underarmour.ae) 정가 — 취소선 정가가 글자 대신 <span class="value" content="799.00">이고 추천 상품 칸에도 취소선이 있음.
    ① 이 상품 품번: 상품 상세 칸(data-gtm-onload="pdpView" 태그)의 data-variation-group-id가 pre + 품번(나이키 NKCW2288-111 · 언더아머 UA1372586-001)
    ② 이 상품 GTM 상세(data-gtm-enhance-commerce-details · ecommerce.detail) 판매가 price = JSON-LD 판매가(sale)
    ③ 취소선 정가 = 바로 앞 가격 칸 표시가 이 상품 가격 칸(b-pdp__priceline·product-detail__priceline·b-microproduct__price — product-tile은 추천 상품)이고
       같은 칸 판매가(sales content)가 sale인 것 · 한 가지 · 판매가보다 높고 5배 안 · GTM 정가 item_original_price와 같아야 함
    ④ 취소선이 없으면 GTM 정가가 판매가와 같을 때만 판매가가 정가(할인 중인데 취소선 정가를 못 읽으면 실패 — 할인가를 정가로 쓰지 않음)"""
    if re.search(r'data-producttype-memberonly="true"', html):
        raise RuntimeError("회원 전용 상품 — 넣지 않음")
    want, dets = (pre + code).upper(), {}
    for m in re.finditer(r'data-variation-group-id="([^"]+)"', html):
        e = html.find("<", m.end())
        tag = html[html.rfind("<", 0, m.start()):e if e >= 0 else len(html)]   # 그 태그(속성 값에는 < 가 없음 — &lt;)
        gm = re.search(r'data-gtm-enhance-commerce-details="([^"]*)"', tag)
        if 'data-gtm-onload="pdpView"' not in tag or not gm:
            continue   # 상품 상세 칸이 아님
        try:
            ps = ((json.loads(unescape(gm.group(1))).get("ecommerce") or {}).get("detail") or {}).get("products") or []
        except (ValueError, AttributeError):
            continue
        if ps and isinstance(ps[0], dict):
            dets[m.group(1).upper()] = ps[0]
    if len(dets) != 1:
        raise RuntimeError(f"이 상품 상세 칸(GTM 상세) {len(dets)}개 — 페이지 모양이 바뀜(정가 확인 안 됨)")
    vg, d = dets.popitem()
    if vg != want and not vg.startswith(want + "-"):
        raise RuntimeError(f"품번 표시가 다름({vg}) — 다른 상품으로 바뀜(대응표 확인)")
    gp, go = num(d.get("price")), num(d.get("item_original_price"))
    if not sale or not gp or abs(gp - sale) > 0.01 or not go:
        raise RuntimeError(f"판매가가 서로 다름(JSON-LD {sale} · GTM {d.get('price')}/{d.get('item_original_price')})")
    lps = set()
    for m in SFRA_STRIKE.finditer(html):
        box = list(SFRA_BOX.finditer(html, max(0, m.start() - 1500), m.start()))
        if not box or box[-1].group(0) == "product-tile":
            continue   # 이 상품 가격 칸이 아님(추천 상품 칸 · 표시 없음)
        nxt = SFRA_BOX.search(html, m.end())
        sm = SFRA_SALES.search(html[box[-1].start():nxt.start() if nxt else m.end() + 1500])   # 같은 가격 칸 안 판매가(나이키는 취소선 뒤 · 언더아머는 앞)
        lp, sv = num(m.group(1)), num(sm.group(1)) if sm else None
        if lp and sv and abs(sv - sale) < 0.01 and sv < lp <= sv * 5:
            lps.add(lp)
    if len(lps) > 1:
        raise RuntimeError(f"이 상품 취소선 정가가 여러 가지({', '.join(f'{x:g}' for x in sorted(lps))})")
    if lps:
        lp = lps.pop()
        if abs(lp - go) > 0.01:
            raise RuntimeError(f"취소선 정가 {lp:g} ≠ GTM 정가 {go:g}")
        return lp
    if go > sale * 1.005:
        raise RuntimeError(f"할인가 {sale:g}만 읽힘(GTM 정가 {go:g} · 취소선 정가 칸을 못 찾음) — 할인가를 정가로 쓰지 않음")
    return sale


_JQ = r'\\*"'   # v1.27 화면 데이터 따옴표 — 그대로(")·한 번 감쌈(\" — Next.js 화면 데이터는 글 안 JSON)·두 번 감쌈 모두


def _jobj(h, i, head=False, lim=4000):
    """v1.27 h[i]를 감싼 가장 안쪽 { } 의 바깥 칸 글(안쪽 { }·[ ] 값은 뺌) — head면 i 뒤 첫 안쪽 묶음 앞까지만(큰 변형 목록을 건너뜀) · 못 찾으면 ''.
    따옴표 안 괄호는 셈하지 않음(크록스 변형 묶음에는 없음 — 괄호가 섞여 묶음을 못 찾으면 그 변형은 빠지고, 다 빠지면 실패)"""
    d, a = 0, i
    while a > 0 and i - a < lim:
        a -= 1
        c = h[a]
        if c in "}]":
            d += 1
        elif c in "{[":
            if d:
                d -= 1
                continue
            if c == "[":
                return ""   # 배열 바로 안 — 묶음이 아님
            out, d, b = [], 0, a + 1
            while b < len(h) and b - a < lim:
                c = h[b]
                if c in "{[":
                    if head and b > i:
                        return "".join(out)
                    d += 1
                elif c in "}]":
                    if not d:
                        return "".join(out)
                    d -= 1
                elif not d:
                    out.append(c)
                b += 1
            return ""
    return ""


def _jval(seg, k):
    """v1.27 묶음 바깥 칸 글에서 키 k의 값(글·숫자·null·true·false) — 없으면 None"""
    m = re.search(rf'{_JQ}{k}{_JQ}\s*:\s*(?:{_JQ}([^"\\]*){_JQ}|(-?[0-9][0-9.]*|null|true|false))', seg)
    return None if not m else m.group(1) if m.group(1) is not None else m.group(2)


def crocs_list(html, code, cur, color=None):
    """v1.27 크록스 공식몰(CROCS — 한국·미국·영국·일본·독일 같은 Next.js 몰) 정가. JSON-LD Offer 가격은 지금 판매가 하나뿐
    (11/21 블프: 미국 클래식 클로그 JSON-LD $30 · 정가 $49.99 · 일본 ￥3,850 · 정가 ￥7,700)이라 화면 데이터의 이 상품 변형 묶음
    {"price":지금 값,"retailPrice":정가,"productId":"품번-색상-사이즈",…}(글 안 JSON이라 따옴표가 \\" — 그대로 쓴 JSON도)을 읽음.
    ① 이 상품만: productId가 '품번-'으로 시작하는 변형(추천 상품 칸은 다른 품번) · JSON-LD 상품이 있으면 sku가 이 품번이어야(다른 상품 페이지로 넘어감 방지)
    ② 정가 = 그 변형 retailPrice 중 가장 높은 값(상품 묶음 masterProductId = 품번의 retailPrice도) · 지금 가장 싼 값 = 주문 가능한 변형 price·JSON-LD 판매가 중 가장 낮은 값
      (v1.27 — 한국 몰 품절 변형은 자리표시 값 "price":10000·14900(orderable false · ats 0 · 정가 69,900)이라 뺌 · 주문 가능 = orderable true, 그 칸이 없으면 ats > 0 ·
      주문 가능 변형 값도 JSON-LD 판매가도 없을 때만 상품 묶음 price)
    ③ 통화: JSON-LD 판매가나 상품 묶음 currency가 이 나라 통화여야(다른 통화가 보이면 실패) · 판매: JSON-LD 판매가가 있거나 주문 가능한(orderable) 변형이 있어야
    ④ 실패(할인가를 정가로 쓰지 않음): 변형 없음 · 변형 정가(retailPrice) 없음 · 정가보다 높은 판매가 · 정가가 지금 값의 5배 넘음"""
    nodes = [n for n in _ld_nodes(html, REL) if _types(n) & {"product", "productgroup"}]
    ld, ld_bad = [], set()
    if nodes:
        mine = [n for n in nodes if code.lower() in {str(n.get(k) or "").strip().lower() for k in ("sku", "productID", "productGroupID", "mpn")}]
        if not mine:
            skus = sorted({str(n.get("sku") or n.get("productID") or "?") for n in nodes})
            raise RuntimeError(f"JSON-LD 품번이 다름({', '.join(skus)[:40]}) — 다른 상품 페이지로 바뀜(대응표 확인)")
        st = [n.get("offers") for n in mine]
        while st:
            x = st.pop()
            if isinstance(x, list):
                st.extend(x)
            elif isinstance(x, dict):
                v, c = num(x.get("price") or x.get("lowPrice")), str(x.get("priceCurrency") or "")
                if v and c == cur:
                    ld.append(v)
                elif v and c:
                    ld_bad.add(c)
                if x.get("offers"):
                    st.append(x.get("offers"))
    pcur, plist, pnow = set(), [], []
    for m in re.finditer(rf'{_JQ}masterProductId{_JQ}\s*:\s*{_JQ}{re.escape(code)}{_JQ}', html):   # 이 상품 묶음(변형 목록 앞 칸 — 통화·정가·지금 값)
        seg = _jobj(html, m.start(), head=True)
        if seg:
            c = _jval(seg, "currency")
            if c:
                pcur.add(c)
            plist.append(num(_jval(seg, "retailPrice"))); pnow.append(num(_jval(seg, "price")))
    rows = {}
    vpre = f"{code}-{color}-" if color else f"{code}-"   # v1.29 색상 하나(SKU 단계 — 품번-색상)면 그 색상 변형만
    for m in re.finditer(rf'{_JQ}productId{_JQ}\s*:\s*{_JQ}({re.escape(vpre)}[^"\\]+){_JQ}', html):   # 이 상품 변형(품번-색상-사이즈)
        seg = _jobj(html, m.start())
        if seg:
            od = _jval(seg, "orderable")   # v1.27 주문 가능 = orderable true · 그 칸이 없으면 재고(ats) > 0
            rows.setdefault(m.group(1).upper(), set()).add((num(_jval(seg, "price")), num(_jval(seg, "retailPrice")),
                                                            od == "true" if od in ("true", "false") else bool(num(_jval(seg, "ats")))))
    vs = [x for s in rows.values() for x in s]
    if not vs:
        raise RuntimeError(f"화면 데이터에 이 상품 변형(productId {code}-…) 없음 — 이 나라 몰에 없거나 페이지 모양이 바뀜")
    lps = [r for _, r, _ in vs if r]
    if not lps:
        raise RuntimeError("변형 정가(retailPrice) 없음 — 정가 확인 안 됨(할인가를 정가로 쓰지 않음)")
    bad = sorted({c for c in pcur if c != cur} | ld_bad)
    if bad:
        raise RuntimeError(f"{cur} 가격 없음(통화 {', '.join(bad)})")
    if not ld and cur not in pcur:
        raise RuntimeError(f"{cur} 가격 없음(통화 확인 안 됨 — JSON-LD 판매가·상품 묶음 currency 없음)")
    if color:   # v1.29 색상 하나 — 상품 묶음 정가·지금 값과 JSON-LD 판매가는 모델 단위라 빼고 그 색상 변형으로만(품절 색상도 정가는 읽음)
        plist, pnow, ld = [], [], []
    elif not ld and not any(o for _, _, o in vs):
        raise RuntimeError(f"{cur} 판매 가격 없음 — 품절·이 나라 몰에서 팔지 않음")
    full = max(lps + [x for x in plist if x])
    hi = [(p, r) for p, r, _ in vs if p and r and p > r * 1.005]
    if hi:
        raise RuntimeError(f"판매가가 정가보다 높은 변형({hi[0][0]:g} > {hi[0][1]:g}) — 값이 이상함")
    nows = [p for p, _, _ in vs if p] + [x for x in pnow if x] + ld
    if nows and max(nows) > full * 1.005:
        raise RuntimeError(f"판매가 {max(nows):g}가 정가 {full:g}보다 높음 — 값이 이상함")
    # v1.27 지금 값은 주문 가능한 변형·JSON-LD 판매가로만 — 한국 품절 변형의 자리표시 "price":10000이 5배 가드에 걸림(11/21 클래식 클로그 10001·바야 라인드 205969)
    buy = [p for p, _, o in vs if p and o] + ld or [x for x in pnow if x]
    low = min(buy) if buy else full
    if full > low * 5:
        raise RuntimeError(f"정가 {full:g}가 지금 값 {low:g}의 5배 넘음 — 값이 이상함")
    return full, {"cur_price": low if low < full * 0.995 else full, "by": "품번"}


def shopify_price(url, code, cur):
    return _shop_price_p(_json(get(url)).get("product") or {}, url, code, cur)


def _shop_price_p(p, url, code, cur):
    """v1.29 쇼피파이 상품(.json의 product) → 정가 — SKU 단계는 한 번 받은 상품으로 품번마다"""
    vs = [v for v in p.get("variants") or [] if isinstance(v, dict) and code.lower() in str(v.get("sku", "")).lower()]
    tags = p.get("tags") if isinstance(p.get("tags"), list) else str(p.get("tags") or "").split(",")
    if not vs and (code.lower().replace("-", "") in str(p.get("handle", "")).lower().replace("-", "")
                   or code.lower() in {str(t).strip().lower() for t in tags}):
        vs = [v for v in p.get("variants") or [] if isinstance(v, dict)]   # 변형 품번이 바코드인 몰 — 상품 주소(handle, 헌터 미국·영국)나 상품 태그(킨 미국·독일)에 품번
    if not vs and len(p.get("variants") or []) >= 250:   # v1.17 쇼피파이 상품 .json은 변형 250개까지만 — 그 뒤 색상은 응답에 없음(대응표 문제가 아닐 수 있음)
        raise RuntimeError("이 품번 변형이 응답에 없음 — 상품 .json이 변형 250개에서 잘림(쇼피파이 한도 · 이 색상이 뒤로 밀렸을 수 있음)")
    if not vs:
        raise RuntimeError("품번이 다른 상품(대응표 확인)")
    # 쇼피파이 마켓은 접속한 나라 통화로 보여 줄 수 있음(GitHub 서버가 멕시코면 페소) — 변형의 통화 표시가 다르면 실패(이전 값 유지)
    bad = {str(v.get(k)) for v in vs for k in ("price_currency", "compare_at_price_currency") if v.get(k) and str(v.get(k)) != cur}
    if bad:
        raise RuntimeError(f"{cur} 가격 없음(통화 {', '.join(sorted(bad))} — 접속한 서버 나라 통화)")
    full = max(max(num(v.get("price")) or 0, num(v.get("compare_at_price")) or 0) for v in vs)
    if not full:
        raise RuntimeError("가격 없음")
    extra = {"cur_price": min(num(v.get("price")) or full for v in vs),
             "lst": any((num(v.get("compare_at_price")) or 0) > (num(v.get("price")) or 0) for v in vs)}   # v1.29 정가 표시(compare_at)로 읽었는지
    k = SHOP_MODEL.get(urllib.parse.urlsplit(url).netloc)
    if k and not any(num(v.get("compare_at_price")) for v in vs):   # v1.17 할인 표시 없이 일부 색상 값만 내리는 몰(on.ae) — 같은 모델 다른 색상이 더 비싸면 정가 확인 안 됨
        top = max([num(v.get("price")) or 0 for v in p.get("variants") or [] if isinstance(v, dict)
                   and str(v.get("sku", "")).upper().startswith(code.upper()[:k])] or [0])
        if top > full * 1.005:
            extra["unsure"] = f"이 색상만 값이 낮음({full:g} · 같은 모델 다른 색상 {top:g} — 할인 표시 없는 할인으로 보임) — 처음 값으로 쓰지 않음"
    return full, extra


def godo_price(html, cur, code):
    """고도몰형 한국 몰(킨·우포스 — 수입사 LF 공식몰): 상품 정보 칸 품번(ARTICLE · Article No.)이 이 상품 품번과 같을 때만, 이 상품 주문 칸의
    숨은 값 정가(set_goods_fixedPrice)·판매가(set_goods_price) 중 높은 값 — 정가를 비워 두면(0) 판매가 · 같은 칸 값이 여러 가지면 실패"""
    if cur != "KRW":
        raise RuntimeError(f"{cur} 가격 없음")
    arts = {unescape(a).strip().lower() for a in re.findall(r'(?:ARTICLE</td>|Article No\.</th>)\s*<td[^>]*>\s*([^<]+?)\s*</td>', html)}
    if code.lower() not in arts:
        raise RuntimeError(f"상품 정보 칸 품번이 다름({', '.join(sorted(arts))[:40] or '품번 칸 없음'}) — 다른 상품으로 바뀜(대응표 확인)")
    def hid(k):
        vs = {num(v) for v in re.findall(rf'name="{k}"\s+value="([0-9.,]+)"', html)}
        if len(vs) > 1:
            raise RuntimeError(f"{k} 값이 여러 가지")
        return vs.pop() if vs else None
    fp, sp = hid("set_goods_fixedPrice"), hid("set_goods_price")
    if not (fp or sp):
        raise RuntimeError("상품 가격 칸(set_goods_price) 없음")
    return max(fp or 0, sp or 0), {"cur_price": sp or fp}


OT_CODE = re.compile(r"(?i)(?<![0-9a-z])([0-9]{4}[a-z][0-9]{3})[._-]([0-9]{3})(?![0-9])")   # v1.27 오니츠카 품번(1183C102.001 · 유럽 주소 1183c102-001) — 대소문자·구분자 무시하고 견줌


def _otc(s):
    """v1.27 글 속 오니츠카 품번들 → {'1183C102.001', …}(대문자·점으로 맞춤)"""
    return {f"{a.upper()}.{b}" for a, b in OT_CODE.findall(str(s or ""))}


def _ot_dicts(x):
    """v1.27 JSON 안의 dict 모두"""
    st = [x]
    while st:
        y = st.pop()
        if isinstance(y, dict):
            yield y
            st.extend(y.values())
        elif isinstance(y, list):
            st.extend(y)


def _ot_one(vals, what):
    """v1.27 같은 뜻의 값들 → 하나(0.5% 넘게 다르면 실패 — 어느 값이 이 상품 것인지 모름)"""
    vs = sorted({v for v in vals if v})
    if vs and vs[-1] > vs[0] * 1.005:
        raise RuntimeError(f"{what} 값이 여러 가지({', '.join(f'{v:g}' for v in vs)})")
    return vs[-1] if vs else None


def ot_price(html, cur, code, url=""):
    """v1.27 오니츠카타이거 몰(마젠토 — 한국 /kr/ko-kr/product/{이름}/{품번} · 유럽 /gb/en-gb/{이름}/p/{품번}.html) 정가.
    JSON-LD가 없고 한국은 가격 칸을 화면 스크립트(knockout)가 그림 → 페이지에 든 화면 데이터에서 이 상품 것만:
    ① dataLayer(dl4Objects · dataLayer.push)의 view_item 상품 중 item_id가 이 품번인 것 — originalPrice = 정가 · price = 지금 가격
       (추천 상품 목록 view_item_list 등은 안 봄 · 할인 상품 표시 item_sale_product)
    ② 마젠토 상품 데이터(x-magento-init)의 price_info — 그 상품 주소(url)에 이 품번이 있는 것(주소가 없으면 상품 화면 provider에 상품이 하나뿐일 때만)
       · regular_price(사이즈별 정가 max·minimal이 같아야) = 정가 · final_price = 지금 가격
    ③ 마젠토 가격 칸(data-price-type oldPrice·finalPrice) — 장바구니 폼 안(</form> 전) 상품 번호(name="product")와 같은 번호의 칸만(추천 상품 칸 빼고) · 주소에 이 품번이 있을 때만
    있는 곳끼리 정가·지금 가격이 같아야(0.5% 안) · 정가가 ①에만 있으면 할인 상품 표시와 맞아야(Yes = 할인 중 · No = 정가 그대로) ·
    할인 상품 표시인데 정가 = 지금 가격이면 실패 · og 가격(product:price:amount)이 있으면 정가·지금 가격 중 하나와 같아야 · 통화가 확인돼야 —
    확인이 안 되면 실패(할인가를 정가로 쓰지 않음 · page_price로 넘기지 않음)"""
    want = _otc(code)
    if len(want) != 1:
        raise RuntimeError(f"오니츠카 품번 꼴이 아님({code})")
    at = _otc(urllib.parse.unquote(urllib.parse.urlsplit(url or "").path))
    if at and at != want:
        raise RuntimeError(f"다른 상품 페이지({'/'.join(sorted(at))})로 넘어감 — 이 상품({code})이 몰에서 빠졌을 수 있음")
    curs = set()
    # ① dataLayer view_item — 이 품번 상품만
    dl = []
    for m in re.finditer(r'(?:\bdl4Objects\s*=\s*|\bdataLayer\.push\(\s*)(?=[\[{])', html):
        try:
            d = json.JSONDecoder().raw_decode(html, m.end())[0]
        except ValueError:
            continue
        for top in (d if isinstance(d, list) else [d]):
            if not isinstance(top, dict) or top.get("event") != "view_item":
                continue   # 추천 상품 목록(view_item_list)·장바구니 등은 이 상품 값이 아님
            ec = top.get("ecommerce") if isinstance(top.get("ecommerce"), dict) else {}
            if ec.get("currency"):
                curs.add(str(ec["currency"]))
            for it in ec.get("items") or []:
                if isinstance(it, dict) and _otc(it.get("item_id")) == want:
                    dl.append(it)
    curs |= {str(it["currency"]) for it in dl if it.get("currency")}
    now_a = _ot_one([num(it.get("price")) for it in dl], "dataLayer 지금 가격")
    list_a = _ot_one([num(it.get("originalPrice")) for it in dl], "dataLayer 정가")
    flags = {str(it.get("item_sale_product") or "").strip().lower() for it in dl} - {""}
    if len(flags) > 1:
        raise RuntimeError(f"할인 상품 표시가 여러 가지({', '.join(sorted(flags))})")
    # ② x-magento-init price_info — 이 상품 것만(주소 품번 · 상품 화면 provider의 단 하나)
    pi_l, pi_n, pi_url = [], [], False
    for m in re.finditer(r'<script[^>]*text/x-magento-init[^>]*>(.*?)</script>', html, re.S | re.I):
        if '"price_info"' not in m.group(1):
            continue
        try:
            d = json.loads(m.group(1))
        except ValueError:
            continue
        sole = set()
        for x in _ot_dicts(d):
            for k, v in x.items():
                if "product/view/provider" in str(k) and isinstance(v, dict) and isinstance(v.get("data"), dict):
                    its = v["data"].get("items")
                    if isinstance(its, dict) and len(its) == 1:
                        sole.update(id(y) for y in its.values())
        for x in _ot_dicts(d):
            pi = x.get("price_info")
            if not isinstance(pi, dict) or "final_price" not in pi:
                continue
            uc = _otc(urllib.parse.unquote(str(x.get("url") or "")))
            if not (uc == want or (not uc and id(x) in sole)):
                continue   # 다른 상품(추천·최근 본 상품)
            pi_url = pi_url or uc == want
            if x.get("currency_code"):
                curs.add(str(x["currency_code"]))
            pi_l.append(_ot_one([num(pi.get(k)) for k in ("regular_price", "max_regular_price", "minimal_regular_price")], "price_info 사이즈별 정가"))
            pi_n.append(num(pi.get("final_price")) or num(pi.get("minimal_price")))
    list_b, now_b = _ot_one(pi_l, "price_info 정가"), _ot_one(pi_n, "price_info 지금 가격")
    # ③ 마젠토 가격 칸 — 장바구니 폼 상품 번호와 같은 칸만(가격 칸에는 품번이 없어 주소 품번으로 확인)
    list_c = now_c = None
    fm = re.search(r'id="product_addtocart_form"', html)
    fb = html[fm.end():fm.end() + 6000].split("</form>")[0] if fm else ""   # 폼 안(</form> 전 · 6000자 안)만 — 폼 밖 다른 상품 번호를 쓰지 않음
    pm = re.search(r'<input[^>]*\bname="product"[^>]*>', fb) if fm else None
    vm = re.search(r'\bvalue="(\d+)"', pm.group(0)) if pm else None
    if vm and at == want:
        got = {"oldPrice": [], "finalPrice": []}
        for t in re.finditer(r'<span\b[^>]*\bdata-price-type="(oldPrice|finalPrice)"[^>]*>', html):
            im = re.search(r'\bid="(?:old-price|product-price)-(\d+)"', t.group(0))
            am = re.search(r'\bdata-price-amount="([0-9.]+)"', t.group(0))
            if im and am and im.group(1) == vm.group(1):
                got[t.group(1)].append(num(am.group(1)))
        now_c = _ot_one(got["finalPrice"], "가격 칸 지금 가격")
        list_c = _ot_one(got["oldPrice"], "가격 칸 정가") if now_c else None
    if not (dl or pi_l or now_c):
        raise RuntimeError("이 상품 가격 데이터 없음(dataLayer view_item·price_info·가격 칸) — 페이지 모양이 바뀜(덤프로 확인)")
    if not (dl or pi_url or at == want):
        raise RuntimeError(f"이 상품 품번({code}) 확인 안 됨 — 주소·dataLayer에 품번 없음")
    lists = {k: v for k, v in (("dataLayer", list_a), ("price_info", list_b), ("가격 칸", list_c)) if v}
    nows = {k: v for k, v in (("dataLayer", now_a), ("price_info", now_b), ("가격 칸", now_c)) if v}
    if not lists:
        raise RuntimeError(f"정가 칸 없음(지금 가격 {', '.join(f'{v:g}' for v in nows.values())}만) — 할인가를 정가로 쓰지 않음")
    full = _ot_one(lists.values(), f"정가({'·'.join(lists)})")
    now = _ot_one(nows.values(), f"지금 가격({'·'.join(nows)})") or full
    if now > full * 1.005 or full > now * 5:
        raise RuntimeError(f"정가 {full:g} · 지금 가격 {now:g}이 맞지 않음")
    sale = now < full * 0.995
    if "yes" in flags and not sale:
        raise RuntimeError(f"할인 상품 표시인데 정가 = 지금 가격({full:g}) — 정가 확인 안 됨(할인가를 정가로 쓰지 않음)")
    if len(lists) < 2 and not set(lists) & {"price_info", "가격 칸"} and flags != {"yes" if sale else "no"}:
        raise RuntimeError(f"정가가 dataLayer에만 있고 할인 상품 표시({'/'.join(flags) or '없음'})와 맞지 않음 — 확인 안 됨")
    mc = re.search(r'<meta[^>]*property="product:price:currency"[^>]*content="([A-Za-z]{3})"', html)
    if mc:
        curs.add(mc.group(1).upper())
    if not curs or curs != {cur}:
        raise RuntimeError(f"{cur} 가격 없음(통화 {', '.join(sorted(curs)) or '확인 안 됨'})")
    ma = re.search(r'<meta[^>]*property="product:price:amount"[^>]*content="([0-9.,]+)"', html)
    v = num(ma.group(1)) if ma else None
    if v and not any(abs(v - x) <= x * 0.005 for x in (full, now)):
        raise RuntimeError(f"og 가격 {v:g}이 정가 {full:g}·지금 가격 {now:g}과 다름 — 확인 안 됨")
    return full, {"cur_price": now, "by": "품번", "how": "·".join(lists)}


def _feed(prod, cc):
    """v1.17 나이키 상품 정보(product_feed)로 받는 값 — 나이키 상품이라도 urls에 있는 나라(두바이)는 페이지로 읽음(페이지 값처럼 할인 가드·크게 바뀜)"""
    return prod["src"] == "nike" and cc not in (prod.get("urls") or {})


def paused_of(prod, cc):
    """v1.19 이 값의 사이트가 수집을 멈춘 사이트(PAUSED)면 {since, why}, 아니면 None — 나이키 상품 정보(product_feed) 값은 해당 없음 ·
    v1.28 나라 단위 수집 중단(PAUSED_CC)이 먼저(나이키 상품 정보 값에도)"""
    if cc in PAUSED_CC:   # v1.28 나라 단위 수집 중단(나이키 상품 정보 값도)
        return PAUSED_CC[cc]
    u = None if _feed(prod, cc) else (prod.get("urls") or {}).get(cc)
    return PAUSED.get(urllib.parse.urlsplit(u).netloc) if u else None


def ccs(prod):
    """v1.17 상품이 받는 나라 — 나이키는 상품 정보 나라(cc) + 페이지 나라(urls), 그 밖은 urls"""
    if prod["src"] == "nike":
        return list(prod["cc"]) + [cc for cc in prod.get("urls") or {} if cc not in prod["cc"]]
    return list(prod["urls"])


def fetch_one(prod, cc):
    cur = MK[cc][2]
    code = (prod.get("cc_code") or {}).get(cc, prod["code"])   # 그 나라 수입사 품번이 따로 있으면(브룩스 일본)
    if _feed(prod, cc):
        return nike_price(prod["code"], cc), NIKE_FEED.format(m=MK[cc][0], l=MK[cc][1], s=prod["code"])
    url = prod["urls"].get(cc)
    if not url:
        raise Skip("주소 없음")
    if url.endswith(".json"):
        return shopify_price(url, code, cur), url[:-5]
    r = get(url)
    loc = urllib.parse.urlsplit(url).path.split("/")[1]
    if prod["id"].startswith("on-") and loc not in urllib.parse.urlsplit(r.url).path:   # 온: 그 나라 몰이 없으면 다른 나라로 넘김
        raise Skip(f"다른 나라 몰로 넘어감({urllib.parse.urlsplit(r.url).path.split('/')[1]})")
    if prod["id"].startswith("on-"):   # v1.20 그 나라 몰에서 빠진 색상은 목록(/shop)으로 넘어감(11/10 한국·일본) — 다른 상품 페이지로 넘어가도 이름으로 엉뚱한 값을 읽지 않게
        fp = urllib.parse.urlsplit(r.url).path
        if "/products/" not in fp:
            raise RuntimeError(f"상품 페이지가 목록({fp})으로 넘어감 — 그 나라 몰에서 빠짐(다른 색상·새 모델로 바꿈)")
        mod = lambda pth: pth.split("/products/", 1)[1].split("/", 1)[0] if "/products/" in pth else ""
        if mod(fp) != mod(urllib.parse.urlsplit(url).path):   # 같은 모델 다른 색상으로 넘어간 것은 예전처럼(온러닝 정가는 모델마다 같음 — 이름으로 찾음)
            raise RuntimeError(f"다른 모델 페이지({mod(fp)})로 넘어감 — 이 상품({mod(urllib.parse.urlsplit(url).path)})이 그 나라 몰에서 빠짐")
    if prod.get("code_in_page") and code.lower() not in r.text.lower():   # 품번이 JSON-LD 밖에만 있는 몰 — 페이지에 품번이 없으면 다른 상품
        raise RuntimeError(f"페이지에 품번({code}) 없음 — 다른 상품으로 바뀜(대응표 확인)")
    if 'name="set_goods_fixedPrice"' in r.text:   # 고도몰형 한국 몰(킨·우포스) — JSON-LD 없음, 상품 정보 칸 품번으로 확인
        return godo_price(r.text, cur, code), url
    if urllib.parse.urlsplit(url).netloc in OT_LIST:   # v1.27 오니츠카타이거 몰 — 이 상품 화면 데이터로만(넘겨진 최종 주소의 품번도 확인)
        return ot_price(r.text, cur, code, r.url), url
    host = urllib.parse.urlsplit(url).netloc
    if host in CROCS:   # v1.27 크록스 — JSON-LD 가격은 지금 판매가 하나뿐 → 화면 데이터의 이 상품 변형 정가(crocs_list)
        return crocs_list(r.text, code, cur), url
    full, extra = page_price(r.text, prod.get("hint") or code, cur, [code] + prod.get("alt", []))   # 나이키 상품은 hint 없음(품번으로만 찾음)
    if host in SFRA_LIST:   # v1.17 두바이 SFCC 몰 — 이 상품 품번 표시·GTM 상세로 확인한 취소선 정가(할인 중이면 JSON-LD는 판매가뿐)
        if extra.get("cur_price") is None or abs(full - extra["cur_price"]) > 0.01:
            raise RuntimeError(f"JSON-LD 가격이 여러 가지({full:g} · {extra.get('cur_price')})")
        full = sfra_list(r.text, code, SFRA_LIST[host], extra["cur_price"])
        extra["by"] = "품번"   # data-variation-group-id로 확인(JSON-LD 품번이 바코드인 언더아머 상품도)
    if host in CAFE24_LIST:   # v1.13 카페24 몰 소비자가 칸 — 할인 중이면 JSON-LD에 판매가만
        lp = cafe24_list(r.text, full)
        if lp:
            full = lp
    if host in CAFE24_ID_LIST or host in BIGC_LIST:   # v1.27 카페24 기본 정보 칸(미즈노 한국)·빅커머스(미즈노 미국) — 할인 중이면 JSON-LD에 판매가만
        lp, sv = (cafe24_id_list if host in CAFE24_ID_LIST else bigc_list)(r.text, full)
        if lp:
            full = lp
            extra["cur_price"] = min(x for x in (extra.get("cur_price"), sv) if x)   # 할인가 = 지금 가장 싼 값(JSON-LD 변형·판매가 칸 중)
    return (full, extra), url


def apply_obs(o, full, extra, cur, td, feed, src_url, age):
    """v1.29 받은 정가 하나를 이전 값 o에 반영(크게 바뀜 보류·할인 가드·정가 변동 기록·할인가) — 대표 상품(_value)과 SKU 단계가 함께 씀.
    feed = 나이키 상품 정보 정가(fullPrice — 할인 가드 없음 · 내려도 크게 바뀜 확인) · age(날짜 글) = 오늘까지 날수 · 돌려줌 (o, 셈 n, 줄 note)"""
    n = {"try": 1}
    full = round(full, 2)
    note, held, guard = "", False, False
    same = o.get("p") and o.get("cur") == cur
    hist = {k: o[k] for k in ("sh", "ph") if same and isinstance(o.get(k), list)}   # v1.5 기록은 통화가 같을 때만 이어 감
    seen_off = bool(same and (o.get("sh") or o.get("off_seen") or (o.get("sale") is False and not o.get("cand"))))   # 할인 아닌 상태를 본 적 있음(그 뒤 할인 = 할인 시작 · 보류 중 sale False는 판단 안 한 것 — 보류 전에 본 것은 off_seen으로 이어 감)
    big = same and (full > o["p"] * JUMP or (feed and full < o["p"] / JUMP))
    if big and not (o.get("cand") and abs(o["cand"] - full) <= o["cand"] * 0.10):   # 크게 바뀜 — 다음 확인 때 비슷하면 반영
        n["hold"] = 1; held = True
        o.update(cand=full, cand_date=td, obs=full, obs_date=td, url=src_url, sale=False)
        o.pop("stale_since", None); o.pop("why", None)
        o.pop("sp", None); o.pop("sp_date", None)   # v1.5 보류 중엔 할인 판단 안 함(어느 정가 기준인지 모름) — 할인 기록 sh는 그대로 두고 확인 뒤 이어 감
        if seen_off:
            o["off_seen"] = True
        note = f"정가 {o['p']:,g} {cur} 유지(이번 {full:,g} — 크게 바뀜, 다음 확인 때 비슷하면 반영)"
    elif (same and not big and not feed and full < o["p"] * 0.995
          and age(o.get("seen") or td) < SALE_GUARD):   # 할인 가드
        o.update(obs=full, obs_date=td, sale=True, url=src_url)
        for k in ("stale_since", "why", "cand", "cand_date", "off_seen"): o.pop(k, None)
        note, guard = f"정가 {o['p']:,g} {cur} 유지(이번 {full:,g} — 할인으로 봄)", True
    else:
        old_p = o.get("p") if same else None
        o = {"p": full, "cur": cur, "seen": td, "url": src_url, "obs": full, "obs_date": td, "sale": False, **hist}
        note = f"정가 {full:,g} {cur}"
        if old_p and abs(full - old_p) > old_p * 0.005:   # v1.5 정가 변동 기록(크게 바뀐 값은 다음 확인에서 반영된 날)
            o["ph"] = (o.get("ph") or [])[-(PH_MAX - 1):] + [[td, old_p, full]]
            note += f" (전 {old_p:,g} → {(full / old_p - 1) * 100:+.1f}%)"
    # v1.5 할인가 — 지금 가장 싼 색상·사이즈(cur_price). 할인 가드로 정가를 지킨 날은 이번에 보인 값(full)도 할인가 후보
    if not held:
        cands = [v for v in (extra.get("cur_price"), full if guard else None) if v]
        note_sale(o, min(cands) if cands else None, td, seen_off)
    return o, n, note


def cfg_hash():   # v1.23 분류(cat)는 화면 착지 계산용이라 빼고 셈 — 분류만 바꾼 날 전체를 다시 받지 않음
    return hashlib.sha1(json.dumps([{k: v for k, v in p.items() if k != "cat"} for p in PRODUCTS], ensure_ascii=False, sort_keys=True).encode()).hexdigest()[:12]


def _hosts(p):
    """상품이 요청하는 사이트(나라마다 하나)"""
    return [urllib.parse.urlsplit(NIKE_FEED if _feed(p, cc) else p["urls"][cc]).netloc for cc in ccs(p)]   # v1.17 나이키 페이지 나라(두바이)는 그 사이트


KR_GAP = 3   # 초 — v1.28 한국 값만 받는 사이트의 요청 간격(한국 값을 먼저 몰아 받으니 한국 몰에 1.5초 간격 요청이 이어지지 않게 · 해외와 함께 쓰는 사이트는 그대로)


def _kr_only_hosts(products):
    """v1.28 한국 값만 요청하는 사이트(해외 나라 값이 하나도 없는 사이트 — 나이키 상품 정보·온러닝·톰브라운·오니츠카처럼 나라를 함께 쓰는 사이트는 빠짐)"""
    kr, other = set(), set()
    for p in products:
        for cc, h in zip(ccs(p), _hosts(p)):
            (kr if cc == "KR" else other).add(h)
    return kr - other


def build_lanes(products):
    """v1.12 동시에 받을 묶음 — 브랜드·사이트(·ROBOTS_ALT·LANE_JOIN)로 이어진 상품끼리 한 묶음, 묶음 안은 PRODUCTS 순서.
    한 사이트·한 브랜드는 늘 한 묶음에만 있음(사이트별 요청 수·한도 미룸·브랜드 셈을 그 묶음만 씀).
    est = 예상 초(값 × max(GAP, HOST_GAP), 한도 사이트는 한도까지) — 긴 묶음부터 시작"""
    for h in _kr_only_hosts(products):   # v1.28 한국 몰 간격(이미 더 긴 간격이 있으면 그대로)
        HOST_GAP[h] = max(HOST_GAP.get(h, 0), KR_GAP)
    par = {}
    def find(x):
        par.setdefault(x, x)
        while par[x] != x:
            par[x] = par[par[x]]; x = par[x]
        return x
    def union(a, b):
        par[find(a)] = find(b)
    for p in products:
        for h in _hosts(p):
            union("b:" + p["brand"], "h:" + h)
            if h in ROBOTS_ALT:
                union("h:" + h, "h:" + urllib.parse.urlsplit(ROBOTS_ALT[h]).netloc)
    for a, b in LANE_JOIN:
        union("b:" + a, "b:" + b)
    lanes = {}
    for p in products:
        ln = lanes.setdefault(find("b:" + p["brand"]), {"prods": [], "brands": [], "hosts": collections.Counter()})
        ln["prods"].append(p); ln["hosts"].update(h for cc, h in zip(ccs(p), _hosts(p)) if not paused_of(p, cc))   # v1.28 값 수·예상 시간은 받는 값만(수집 멈춤 값은 요청 안 함)
        if p["brand"] not in ln["brands"]:
            ln["brands"].append(p["brand"])
    for ln in lanes.values():
        ln["name"], ln["n"] = "+".join(ln["brands"]), sum(ln["hosts"].values())
        ln["est"] = sum(min(n, HOST_CAP.get(h, n)) * max(GAP, HOST_GAP.get(h, 0)) for h, n in ln["hosts"].items())
    return list(lanes.values())


def pace_map(products):
    """v1.12 사이트 → 플랫폼 묶음 — 쇼피파이 상품 .json 주소의 사이트 + PACE_EXTRA"""
    pm = {urllib.parse.urlsplit(u).netloc: "shopify" for p in products for u in (p.get("urls") or {}).values() if u.endswith(".json")}
    pm.update(PACE_EXTRA)
    return pm


def _lanes_n():
    try:
        return max(1, min(16, int(os.environ.get("PRICE_LANES") or LANES)))
    except ValueError:
        return LANES


# ── v1.29 SKU 단계: 판매·예정 상품(비공개 목록)의 정가 — 대표 결정 2026-11-22 '비공개로 받기 · 공개 prices.json에 함께 · 판매 중 먼저, 예정은 다음' ──
# 목록 = GitHub Secrets ERP_SKU_URL(주소)·ERP_SKU_TOKEN(Bearer 토큰)의 JSON {"items":[{"brand","code","status":"selling|planned",…}]} — 없으면 이 단계는 건너뜀.
# 저장소·실행 기록이 공개라 목록 주소·토큰·품번·상품명은 찍지 않음(줄은 구간·찾은 상품 수만) · 못 찾은 품번은 파일 어디에도 남기지 않음(다시 물을 날은 상태 없이 품번 해시로 정한 요일 — _sku_slot)
# v1.39 읽지 않는 브랜드(SKU_BRANDS 밖)의 품번은 받자마자 버림(셈도 안 함) · 국내 공식몰에 없음(none)인 파일 밖 품번은 품번 대신 꼬리표만(kr_none — _kr_tag).
# 공식몰에서 찾은 상품만 prices.json items에 kind "sku"로 넣음(판매 상태·목록 출처는 쓰지 않음) — 화면·주간 메일은 kind "sku"를 뺌(대표 상품만).
# 요청은 대표 상품과 같은 get(우리 봇 이름 · robots.txt · 사이트별 간격 · 막히면 그 실행에서 멈춤 — 우회 없음).
SKU_ENV_URL, SKU_ENV_TOKEN, SKU_ENV_TEST = "ERP_SKU_URL", "ERP_SKU_TOKEN", "ERP_SKU_TEST"   # TEST = 공개 품번 시험 목록(JSON · 브랜치 시험용 — 줄을 자세히 찍음)
SKU_MAX = 8 * 60     # 초 — 한 실행 SKU 단계 최대(대표 상품을 받은 뒤 남은 시간 안에서 · TIME_LIMIT 30초 전까지)
SKU_DAYS = 7         # 일 — 받은 값을 다시 받는 주기(오래된 것부터 · 한국 먼저)
SKU_ASK_DAYS = 7     # 일 — 공식몰에서 아직 못 찾은 해외 값을 다시 물어보는 주기(상태 없이 품번 해시로 정한 날 — 파일에 기록 안 남김)
SKU_STALE_EVERY = 3  # 일 — 전에 받았는데 이번에 못 받은 값(이전 값)을 다시 받는 주기
SKU_ASK_KR = 2       # 일 — 한국에서 아직 못 찾은 값을 다시 묻는 주기(목록의 새 상품은 1~2일 안에 · 날마다 순서를 돌림)
SKU_NEW_SHARE = 0.6  # 한국 '아직 못 찾은 값 묻기'는 SKU 단계 시간의 이만큼까지만 — 나머지는 해외·다시 받기 몫(목록에 공식몰에 없는 품번이 많아도)
SKU_HOLD_DAYS = 21   # 일 — 정가 확인 보류 값이 같은 값(5% 안)으로 이만큼 넘게 이어지고 세일 기간(_sku_promo) 밖이면 정가로 받아들임
SKU_META = ("sku_list_fail", "sku_list_told", "kr_none")   # 파일 최상위에 두는 SKU 단계 상태(단계를 건너뛴 날은 그대로 이어 씀)
KR_NONE_PAD = 50     # v1.39 '국내 공식몰에 없음' 목록 품번 꼬리표(kr_none) 개수를 이 단위로 채움 — 가짜 꼬리표를 섞어 실제 개수가 드러나지 않게
KR_NONE_MIN_TOK = 20   # v1.39 목록 토큰이 이보다 짧으면 꼬리표를 쓰지 않음(공개 꼬리표로 짧은 토큰을 짐작해 볼 수 있어 — 검토 11/23)
KR_NONE_ITER = 200000   # v1.39 꼬리표 열쇠를 만드는 PBKDF2 반복 수(느리게 — 공개 꼬리표로 토큰을 짐작해 보기 어렵게 · 검토 11/23)


def _sku_token():
    """ERP 목록 토큰(Bearer 앞머리 뗀 값) — 없으면 빈 글"""
    tok = os.environ.get(SKU_ENV_TOKEN, "").strip()
    return tok[7:].strip() if tok.lower().startswith("bearer ") else tok


def _kr_none_key(test):
    """v1.39 꼬리표 열쇠 = PBKDF2-HMAC-SHA256(목록 토큰, 소금 "kr-none|v1", KR_NONE_ITER번, 32바이트) — ERP(토큰을 만든 쪽)와 모니터만 앎 ·
    느린 열쇠 만들기라 공개 꼬리표로 토큰을 짐작해 보기 어려움(검토 11/23) · 시험 목록이면 고정 시험 열쇠(브랜치 시험 전용)"""
    return hashlib.pbkdf2_hmac("sha256", b"test" if test else _sku_token().encode("utf-8"), b"kr-none|v1", KR_NONE_ITER, 32)


def _kr_tag(key, msg):
    """v1.39 꼬리표 = HMAC-SHA256(열쇠, "날짜|품번")(품번은 빈칸 모두 빼고 대문자) 16진 앞 16자리 — 열쇠 없이는 품번을 알 수 없고,
    날마다 날짜가 바뀌어 어제 꼬리표와 이어 볼 수 없음(가짜 꼬리표 "날짜|pad|n"·확인값 "날짜|check"도 같은 식 — 검토 11/23)"""
    return hmac.new(key, msg.encode("utf-8"), hashlib.sha256).hexdigest()[:16]


def _sku_promo(d):
    """세일 기간(블프·사이버먼데이·연말 세일 — 11/15~1/5): 정가 표시 없는 해외 첫 값은 견줄 값이 없으면 보류 · 보류 값은 이 기간에 받아들이지 않음"""
    return (d.month == 11 and d.day >= 15) or d.month == 12 or (d.month == 1 and d.day <= 5)
SKU_DROP = 60        # 일 — 값이 모두 이만큼 넘게 이전 값(공식몰에서 빠짐)이면 파일에서 뺌 · 목록에서 빠진 상품도 같은 주기로 계속 받음(빠진 날이 드러나지 않게)
SKU_MIN_LEFT = 90    # 초 — 대표 상품 뒤 남은 시간이 이보다 적으면 SKU 단계 건너뜀(목록도 안 받음 — 단계 15분 제한 전에 저장)
SKU_BF = 1.25        # 배 — 정가 표시가 없는 새 값은 대표 상품의 '한국 정가 ÷ 그 나라 정가' 가운데값(브랜드·나라별)에서 이만큼 넘게 싸 보이면 보류(할인가를 정가로 저장하지 않게 — 11/21 블프 검사 자동화)
SKU_CC = ("KR", "US", "GB", "DE", "JP")   # 대표 결정 11-22 — 한국(최우선) + 미국·영국·독일 · v1.30 일본(11-23 — 맨 뒤 차례)
SKU_LANES = 6
