def _sku_norm(c):
    return re.sub(r"\s+", "", str(c or "")).upper()


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    """목록 주소가 다른 곳으로 넘기면 따라가지 않음(토큰이 다른 사이트·http로 가지 않게) — HTTP 3xx 오류로"""
    def redirect_request(self, *a, **k):
        return None


def sku_list(deadline=None):
    """비공개 목록 → ([{brand(감시 브랜드), code, st(0 판매 중 · 1 예정)}], 시험?, 못 받은 까닭) — Secrets가 없으면 (None, False, None).
    주소·토큰·응답 글은 찍지 않음(오류는 HTTP 코드·종류만) · https만 · 넘겨짐은 따라가지 않음 · 서버가 잠든 뒤 첫 요청은 503일 수 있어 15·30·60초 쉬고 다시 —
    deadline(시각)을 넘길 다시 받기는 하지 않음 · 같은 품번이 여럿이면 판매 중이 앞섬 · 모델 단위 브랜드(model)는 모델 번호로 모음"""
    test = os.environ.get(SKU_ENV_TEST, "").strip()
    if test:
        raw, is_test = json.loads(test), True
    else:
        url, tok = os.environ.get(SKU_ENV_URL, "").strip(), _sku_token()
        if not url or not tok:
            return None, False, None
        if not url.lower().startswith("https://"):
            return None, False, "목록 주소가 https가 아님"
        req = urllib.request.Request(url, headers={"Authorization": f"Bearer {tok}", "Accept": "application/json", "User-Agent": UA})
        opener = urllib.request.build_opener(_NoRedirect)
        raw, why = None, ""
        for n, w in enumerate((0, 15, 30, 60), 1):
            if deadline and time.time() + w + 10 > deadline:
                why = (why + " · " if why else "") + "남은 시간 부족"
                break
            time.sleep(w)
            try:
                with opener.open(req, timeout=max(5, min(40, (deadline or time.time() + 40) - time.time()))) as r:
                    d = json.loads(r.read())
                raw = d.get("items") if isinstance(d, dict) else None
                if not isinstance(raw, list):
                    return None, False, "응답에 items 목록 없음"
                break
            except urllib.error.HTTPError as e:
                why = f"HTTP {e.code}"
                if e.code not in (429, 500, 502, 503, 504):
                    break
            except Exception as e:   # 글에 주소가 들어갈 수 있어 종류만
                why = type(e).__name__
        if raw is None:
            return None, False, why or "못 받음"
        if not raw:   # v1.39 빈 목록은 받은 것으로 보지 않음(국내 상태·꼬리표가 한꺼번에 지워지지 않게 — 검토 11/23)
            return None, False, "목록이 비어 있음"
        is_test = False
    # v1.39 (ERP 조건 11/23 '목록 전체 확대') 모니터가 읽지 않는 브랜드(SKU_BRANDS 밖 — 감시 브랜드 밖·대표 상품만 받는 브랜드)의 품번은 받자마자 버림:
    # 이름·품번·건수를 셈하지도 공개 파일·실행 기록에 남기지도 않음(미확인 셈은 ERP가 함) · 시험 목록(공개 품번)일 때만 건너뛴 브랜드 이름을 찍음
    out, idx, skip = [], {}, set()
    for it in raw:
        if not isinstance(it, dict):
            continue
        b = _SKU_AL.get(_SKU_KEY(it.get("brand")))
        raw_c = _sku_norm(it.get("code"))   # v1.39 목록에 온 품번 그대로(빈칸 빼고 대문자) — 국내 공식몰에 없음 꼬리표(kr_none)는 이 품번으로(ERP가 같은 꼬리표를 만듦)
        h = SKU_BRANDS.get(b)
        if not h or not raw_c:
            if is_test:
                skip.add(str(it.get("brand") or "?"))
            continue
        c = h["norm"](raw_c) if h.get("norm") else raw_c
        if h.get("model") and (not h.get("rx") or re.match(h["rx"], c)):
            c = h["q"](c)   # 모델 단위 — 색상 품번은 모델 번호로(목록 색상 품번을 파일에 남기지 않음)
        st = 1 if str(it.get("status") or "").lower() == "planned" else 0
        if (b, c) in idx:
            idx[(b, c)]["st"] = min(idx[(b, c)]["st"], st)   # 같은 품번 — 판매 중이 앞섬
            idx[(b, c)]["raw"].add(raw_c)
            continue
        idx[(b, c)] = {"brand": b, "code": c, "st": st, "raw": {raw_c}}; out.append(idx[(b, c)])
    if skip:
        log(f"  SKU 시험 목록: 읽지 않는 브랜드 건너뜀 — {', '.join(sorted(skip))}")
    if not out and not is_test:   # v1.39 읽는 브랜드 품번이 하나도 없으면(목록 칸 이름·브랜드 표기가 바뀜 등) 못 받은 것으로 — 국내 상태·꼬리표가 조용히 지워지지 않게(검토 11/23)
        return None, False, "목록에 읽는 브랜드 품번이 없음"
    return out, is_test, None


def _sku_slot(key, every, today):
    """상태 없이 다시 물을 날 — 품번 해시로 정한 요일(every일마다 하루 · 파일에 기록을 남기지 않음)"""
    return every <= 1 or int(hashlib.sha1(key.encode()).hexdigest()[:8], 16) % every == today.toordinal() % every


def _sku_cat(name, default):
    s = str(name or "").lower()
    for cat, rx in (("bag", r"백팩|가방|토트|더플|크로스백|숄더백|bag|backpack|tote|duffel"), ("sandal", r"슬라이드|샌들|클로그|쪼리|플립|slide|sandal|clog|flip"),
                    ("boot", r"부츠|워커|boot"), ("top", r"티셔츠|반팔|민소매|탱크|컴프레션|t-shirt|tee|tank|short sleeve|싱글렛|singlet|compression"),
                    ("wear", r"재킷|자켓|후디|후드|팬츠|바지|쇼츠|반바지|베스트|조끼|플리스|맨투맨|스웨트|레깅스|jacket|hoodie|pants|shorts|vest|fleece|sweat|legging|crew")):
        if re.search(rx, s):
            return cat
    return default


def _clean_name(x):
    """상품 이름 — HTML 조각(<br> 등)·겹친 빈칸 정리"""
    t = re.sub(r"\s+", " ", re.sub(r"<[^>]*>", " ", unescape(str(x or "")))).strip()
    return t[:80] or None


def _ld_name(html, code=None):
    for n in _ld_nodes(html, REL):
        if _types(n) & {"product", "productgroup"} and n.get("name"):
            return _clean_name(n["name"])
    m = re.search(r'<meta[^>]+property="og:title"[^>]+content="([^"]+)"', html)
    return _clean_name(m.group(1)) if m else None


class _SkuIdx:
    """사이트 색인(사이트맵·쇼피파이 상품 목록) — 실행마다 그 사이트를 처음 쓸 때 한 번만 만듦(못 만들면 None · 까닭은 시험 목록일 때만 찍음 —
    브랜드 이름이 공개 기록에 남지 않게 · 셈은 요약 줄 '색인 못 만듦')"""
    def __init__(self, say=None):
        self.d, self.lock, self.say = {}, threading.Lock(), say or (lambda *_: None)

    def has(self, k):
        with self.lock:
            return k in self.d

    def get(self, k, build):
        with self.lock:
            if k in self.d:
                return self.d[k]
        try:
            v = build()
        except Exception as e:
            self.say(f"  SKU 색인 {k}: 못 만듦 — {type(e).__name__}: {str(e)[:60]}"); v = None
        with self.lock:
            self.d[k] = v
        return v


class _Idx(dict):
    """v1.37 색인 — partial = 시간·쪽 한도로 덜 끝남(색인에 없는 품번을 '국내 공식몰에 없음'으로 보지 않음)"""
    partial = False


class _IdxL(list):
    partial = False


def _sm_walk(start, host, pre, max_maps=20, budget=90):
    """사이트맵 → 그 사이트·경로 주소 목록(색인 · 공개 주소만) · v1.37 한도로 남은 사이트맵이 있으면 partial"""
    import gzip as _gz
    queue, out, seen, t0 = list(start), _IdxL(), 0, time.time()
    while queue and seen < max_maps and time.time() - t0 < budget:
        r = get(queue.pop(0)); seen += 1
        c = r.content
        txt = (_gz.decompress(c) if c[:2] == b"\x1f\x8b" else c).decode("utf-8", "replace")
        locs = [unescape(x) for x in re.findall(r"<loc>\s*([^<\s]+)\s*</loc>", txt)]
        if "<sitemapindex" in txt[:3000]:
            kids = [k for k in locs if urllib.parse.urlsplit(k).netloc == host]
            kids.sort(key=lambda u: (not any(x in u.lower() for x in ("product", "pdp", "prod")), u))
            queue = kids + queue; continue
        out += [u for u in locs if urllib.parse.urlsplit(u).netloc == host and urllib.parse.urlsplit(u).path.startswith(pre)]
    out.partial = bool(queue)
    return out


def _shop_all(base, pages=12, lim=250, stop=None):
    """쇼피파이 몰 상품 목록(products.json · 250개씩) — v1.45 lim None이면 쪽 크기를 정하지 않음(몰 기본 쪽 크기 · robots.txt가 ?limit=를 막으려 한 몰 — 스투시 한국) ·
    stop(시각)을 넘기면 받은 데까지만(덜 끝난 목록 — 색인에 없는 품번을 '없음'으로 보지 않음 · 검토 11/24)"""
    out, n1 = _IdxL(), None
    for page in range(1, pages + 1):
        if stop and time.time() > stop:
            out.partial = True
            break
        ps = _json(get(f"{base}/products.json?limit={lim}&page={page}" if lim else f"{base}/products.json?page={page}")).get("products") or []
        out += [p for p in ps if isinstance(p, dict)]
        n1 = len(ps) if n1 is None else n1
        if not ps or len(ps) < (lim or n1):
            break
    else:
        out.partial = True   # v1.37 쪽 한도까지 꽉 참 — 뒤 상품이 더 있을 수 있음
    return out


def _robots_maps(host):
    return [l.split(":", 1)[1].strip() for l in get(f"https://{host}/robots.txt").text.splitlines() if l.lower().startswith("sitemap:")]


